"""validators.py - input validation with regular expressions"""
import re

ROLL = re.compile(r"^\d{6}$")
NAME = re.compile(r"^[A-Za-z][A-Za-z .]{2,39}$")
PHONE = re.compile(r"^01[3-9]\d{8}$")


class ValidationError(Exception):
    pass


def validate(roll, name, phone, marks_text):
    errors = []
    if not ROLL.fullmatch(roll):
        errors.append("Roll must be exactly 6 digits")
    if not NAME.fullmatch(name):
        errors.append("Name must contain letters only (3-40 characters)")
    if not PHONE.fullmatch(phone):
        errors.append("Phone must be a valid BD number (01XXXXXXXXX)")
    marks = [int(m) for m in re.findall(r"\d+", marks_text)]
    if len(marks) != 3 or any(m > 100 for m in marks):
        errors.append("Enter three marks between 0 and 100")
    if errors:
        raise ValidationError(errors)
    return marks

from validators import validate, ValidationError

for data in [("512309", "Rina Akter", "01711000009", "88, 74, 91"),
             ("51231", "Rina123", "01211000009", "88 74")]:
    try:
        print("Valid! Marks =", validate(*data))
    except ValidationError as e:
        print("Invalid:")
        for msg in e.args[0]:
            print("  -", msg)
